# Glossaire MEDINA — I89 — Lymphœdème et autres atteintes non infectieuses des vaisseaux et ganglions lymphatiques (C-01-Cardiologie), couvre I88 et I89
from cardio_1 import a, G

a('ISL', [('I', 'International'), ('S', 'Society of'), ('L', 'Lymphology')], 'International Society of Lymphology (Société internationale de lymphologie)', '<p>Société savante internationale qui publie le document de consensus sur le diagnostic et le traitement du lymphœdème périphérique. La version 2023 (Lymphology 2023;56:133-151) définit les stades 0 à III et la thérapie décongestive complexe en deux phases.</p>')
a('AMAROS', [('A', 'After'), ('MA', 'MApping of the axilla (après repérage de l’aisselle)'), ('R', 'Radiotherapy'), ('O', 'Or'), ('S', 'Surgery')], 'Essai AMAROS', '<p>Essai européen de phase 3 (Donker et al., Lancet Oncology 2014) chez des patientes avec ganglion sentinelle positif : curage axillaire ou radiothérapie axillaire. Le contrôle axillaire a été comparable. Des signes cliniques de lymphœdème étaient présents à 5 ans chez 23 % des patientes après curage et 11 % après radiothérapie.</p>')
a('PAL', [('P', 'Physical'), ('A', 'Activity and'), ('L', 'Lymphedema')], 'Essai PAL (activité physique et lymphœdème)', '<p>Essai randomisé (Schmitz et al., New England Journal of Medicine 2009) de renforcement musculaire progressif, deux fois par semaine, chez 141 femmes avec lymphœdème stable du bras après cancer du sein. Le gonflement n’a pas augmenté et les poussées ont été moins fréquentes (14 % contre 29 %).</p>')
a('LYMPHA', [('LYMPHA', 'LYMPHatic microsurgical preventive healing Approach (approche microchirurgicale lymphatique préventive)')], 'Technique LYMPHA', '<p>Anastomose lymphaticoveineuse réalisée pendant le curage ganglionnaire, chez un patient à haut risque, pour prévenir le lymphœdème. Plusieurs études suggèrent une baisse de l’incidence ; les données à long terme manquent (ISL 2023).</p>', 'i89-chir-micro')
a('ICG', [('I', 'Indo-'), ('C', 'Cyanine'), ('G', 'Green (vert)')], 'Vert d’indocyanine', '<p>Colorant fluorescent injecté dans le derme. Une caméra proche infrarouge visualise en temps réel les vaisseaux lymphatiques superficiels (lymphographie au vert d’indocyanine), sans rayonnement ionisant.</p>', 'i89-e-icg')
a('BIS', [('B', 'Bio-'), ('I', 'Impedance'), ('S', 'Spectroscopy')], 'Bioimpédance spectroscopique', '<p>Mesure de la résistance du membre à des courants de faible intensité et de fréquences multiples. Le liquide extracellulaire conduit le courant de basse fréquence : son augmentation abaisse la résistance et révèle un lymphœdème avant qu’il ne soit visible.</p>', 'i89-e-bis')
a('L-Dex', [('L', 'Lymphoedema'), ('Dex', 'inDEX (indice)')], 'Indice de lymphœdème mesuré par bioimpédance', '<p>Rapport des résistances entre le membre exposé et le membre sain, normalisé par l’appareil de bioimpédance spectroscopique. Son interprétation exige une mesure de référence avant le traitement du cancer.</p>', 'i89-e-bis')
a('VEGF-C', [('V', 'Vascular (vasculaire)'), ('E', 'Endothelial (endothélial)'), ('G', 'Growth (de croissance)'), ('F', 'Factor (facteur)'), ('C', 'type C')], 'Facteur de croissance de l’endothélium vasculaire C', '<p>Principal facteur de croissance des vaisseaux lymphatiques. Il active le récepteur VEGFR-3 des cellules endothéliales lymphatiques. Certains variants pathogènes de son gène causent un lymphœdème héréditaire.</p>', 'i89-s-vegfc')
a('VEGF-D', [('V', 'Vascular (vasculaire)'), ('E', 'Endothelial (endothélial)'), ('G', 'Growth (de croissance)'), ('F', 'Factor (facteur)'), ('D', 'type D')], 'Facteur de croissance de l’endothélium vasculaire D', '<p>Facteur lymphangiogénique apparenté au VEGF-C. Son taux sérique est élevé dans la lymphangioléiomyomatose et diminue sous sirolimus.</p>')
a('VEGFR-3', [('V', 'Vascular (vasculaire)'), ('E', 'Endothelial (endothélial)'), ('G', 'Growth (de croissance)'), ('F', 'Factor (facteur)'), ('R', 'Receptor (récepteur)'), ('3', 'type 3')], 'Récepteur 3 du facteur de croissance de l’endothélium vasculaire', '<p>Récepteur à activité tyrosine kinase des cellules endothéliales lymphatiques, codé par le gène FLT4. Une perte de fonction cause la maladie de Milroy.</p>', 'i89-s-vegfc')
a('FLT4', [('F', 'Fms- (apparenté au récepteur fms)'), ('L', 'Like (similaire)'), ('T', 'Tyrosine kinase'), ('4', '4')], 'Gène FLT4', '<p>Gène du récepteur VEGFR-3. Ses variants pathogènes, souvent transmis sur un mode autosomique dominant, causent la maladie de Milroy : lymphœdème congénital des pieds et des jambes.</p>')
a('CCBE1', [('C', 'Collagen (collagène)'), ('C', 'Calcium-'), ('B', 'Binding (liant le calcium)'), ('E', 'EGF domain (domaine de type facteur de croissance épidermique)'), ('1', '1')], 'Gène CCBE1', '<p>Gène nécessaire à la maturation du VEGF-C. Ses variants pathogènes causent le syndrome de Hennekam, dysplasie lymphatique généralisée avec lymphangiectasies intestinales.</p>')
a('FAT4', [('FAT', 'FAT (nom du gène « fat » de la drosophile, non développable)'), ('4', '4')], 'Gène FAT4', '<p>Gène d’une cadhérine atypique. Ses variants pathogènes sont une autre cause du syndrome de Hennekam.</p>')
a('GJC2', [('G', 'Gap'), ('J', 'Junction (jonction communicante)'), ('C', 'protein gamma (sous-famille C)'), ('2', '2')], 'Gène GJC2', '<p>Gène de la connexine 47, protéine des jonctions communicantes. Ses variants pathogènes causent un lymphœdème héréditaire des membres.</p>')
a('PIEZO1', [('PIEZO', 'du grec « píesi », pression (canal ionique mécanosensible)'), ('1', '1')], 'Gène PIEZO1', '<p>Gène d’un canal ionique activé par l’étirement. Chez la souris, son absence dans l’endothélium réduit fortement le nombre de valvules lymphatiques (Nonomura et al., 2018). Ses variants pathogènes causent une forme de lymphœdème héréditaire (type III selon l’ISL 2023) et des dysplasies lymphatiques généralisées.</p>')
a('GATA2', [('GATA', 'facteur se liant à la séquence d’ADN G-A-T-A'), ('2', '2')], 'Gène GATA2', '<p>Facteur de transcription hématopoïétique et lymphatique. Ses variants pathogènes causent le syndrome d’Emberger : lymphœdème primaire, infections et risque de myélodysplasie, ce qui impose un suivi hématologique.</p>')
a('SOX18', [('S', 'SRY (région du chromosome Y déterminant le sexe)'), ('OX', '-related HMG bOX (boîte HMG apparentée)'), ('18', '18')], 'Gène SOX18', '<p>Facteur de transcription de la différenciation lymphatique. Ses variants pathogènes causent le syndrome hypotrichose-lymphœdème-télangiectasies.</p>')
a('PROX1', [('PRO', 'PROspero (gène homologue de la drosophile)'), ('X', 'homeoboX (boîte homéotique)'), ('1', '1')], 'Facteur de transcription PROX1', '<p>Facteur qui fixe l’identité des cellules endothéliales lymphatiques pendant le développement. Il sert aussi de marqueur immunohistochimique de ces cellules.</p>')
a('LYVE-1', [('LY', 'LYmphatic (lymphatique)'), ('V', 'Vessel (vaisseau)'), ('E', 'Endothelial hyaluronan receptor (récepteur endothélial de l’hyaluronane)'), ('1', '1')], 'Récepteur endothélial lymphatique de l’hyaluronane 1', '<p>Récepteur de l’hyaluronane exprimé par les lymphatiques initiaux. Il sert de marqueur des capillaires lymphatiques en histologie.</p>')
a('RASA1', [('RAS', 'RAt Sarcoma (oncogène du sarcome du rat)'), ('A', 'Activator (protéine activatrice de la GTPase)'), ('1', '1')], 'Gène RASA1', '<p>Gène d’un régulateur négatif de la voie RAS. Ses variants pathogènes causent des malformations capillaires et artérioveineuses, dont certaines s’accompagnent d’une hypertrophie de membre.</p>')
a('TSC1', [('T', 'Tuberous (tubéreuse)'), ('S', 'Sclerosis (sclérose)'), ('C', 'Complex (complexe)'), ('1', 'gène 1')], 'Gène TSC1', '<p>Gène de l’hamartine, frein de la voie mTOR. Sa perte de fonction, comme celle de TSC2, active mTOR dans la sclérose tubéreuse et la lymphangioléiomyomatose.</p>')
a('TSC2', [('T', 'Tuberous (tubéreuse)'), ('S', 'Sclerosis (sclérose)'), ('C', 'Complex (complexe)'), ('2', 'gène 2')], 'Gène TSC2', '<p>Gène de la tubérine, frein de la voie mTOR. Ses variants pathogènes, comme ceux de TSC1, activent mTOR dans la lymphangioléiomyomatose ; le sirolimus inhibe mTOR.</p>')
a('CD31', [('CD', 'Cluster of Differentiation (classe de différenciation)'), ('31', '31')], 'Antigène CD31', '<p>Molécule d’adhésion des cellules endothéliales (aussi appelée PECAM-1). Son expression par les cellules tumorales confirme la nature vasculaire d’un angiosarcome.</p>')
a('PECAM-1', [('P', 'Platelet (plaquettaire)'), ('E', 'Endothelial (endothéliale)'), ('C', 'Cell (cellulaire)'), ('A', 'Adhesion (d’adhésion)'), ('M', 'Molecule (molécule)'), ('1', '1')], 'Molécule d’adhésion plaquettaire et endothéliale 1', '<p>Autre nom de l’antigène CD31.</p>')
a('ERG', [('E', 'ETS (famille de facteurs de transcription « E26 transformation-specific »)'), ('R', '-Related (apparenté)'), ('G', 'Gene (gène)')], 'Facteur de transcription ERG', '<p>Facteur nucléaire spécifique des cellules endothéliales. Sa détection immunohistochimique aide à confirmer un angiosarcome.</p>')
a('MYC', [('MYC', 'MYéloCytomatose (oncogène du virus de la myélocytomatose aviaire)')], 'Oncogène MYC', '<p>Facteur de transcription de la prolifération cellulaire. Son amplification de haut niveau caractérise une partie des angiosarcomes secondaires à l’irradiation ou au lymphœdème chronique (Manner et al., 2010).</p>')
a('D2-40', [('D2-40', 'nom du clone d’anticorps monoclonal, non développable')], 'Anticorps D2-40 (antipodoplanine)', '<p>Anticorps monoclonal qui reconnaît la podoplanine, glycoprotéine des cellules endothéliales lymphatiques. Il distingue en histologie un vaisseau lymphatique d’un capillaire sanguin.</p>')
a('CLOVES', [('C', 'Congenital (congénitale)'), ('L', 'Lipomatous'), ('O', 'Overgrowth'), ('V', 'Vascular malformations (malformations vasculaires)'), ('E', 'Epidermal nevi (nævus épidermiques)'), ('S', 'Scoliosis, skeletal and spinal anomalies (anomalies rachidiennes et squelettiques)')], 'Syndrome CLOVES', '<p>Syndrome de croissance excessive lié à des variants somatiques de PIK3CA, avec masses lipomateuses et malformations vasculaires, notamment lymphatiques.</p>')
a('Stewart-Treves', [('Stewart', 'Fred W. Stewart, pathologiste américain'), ('Treves', 'Norman Treves, chirurgien américain')], 'Syndrome de Stewart-Treves', '<p>Angiosarcome (lymphangiosarcome) développé sur un lymphœdème chronique, décrit en 1948 après mastectomie. Il se manifeste par des macules ou nodules violacés et a un pronostic sombre.</p>', 'i89-stewart')
a('Q82.0', [('Q82.0', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Lymphœdème héréditaire', '<p>Code CIM-10-GM 2024.</p>')
a('E88.2', [('E88.2', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Lipomatose, non classée ailleurs (dont lipœdème)', '<p>Code CIM-10-GM 2024.</p>')
a('E88.20', [('E88.20', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Lipœdème, stade I', '<p>Code CIM-10-GM 2024.</p>')
a('E88.21', [('E88.21', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Lipœdème, stade II', '<p>Code CIM-10-GM 2024.</p>')
a('E88.22', [('E88.22', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Lipœdème, stade III', '<p>Code CIM-10-GM 2024.</p>')
a('J94.0', [('J94.0', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Épanchement chyleux', '<p>Code CIM-10-GM 2024.</p>')
a('L03.1', [('L03.1', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Phlegmon d’autres parties d’un membre', '<p>Code CIM-10-GM 2024.</p>')
a('L98.4', [('L98.4', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Ulcérations chroniques de la peau, non classées ailleurs', '<p>Code CIM-10-GM 2024.</p>')
a('B74.0', [('B74.0', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Filariose à Wuchereria bancrofti', '<p>Code CIM-10-GM 2024.</p>')
a('R59.0', [('R59.0', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Adénopathies localisées', '<p>Code CIM-10-GM 2024.</p>')
a('R59.9', [('R59.9', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Adénopathie, sans précision', '<p>Code CIM-10-GM 2024.</p>')
a('DiSipio', [('DiSipio', 'nom propre de l’autrice principale de la méta-analyse ; non développable')], 'Méta-analyse de DiSipio et al. (2013)', '<p>Revue systématique et méta-analyse publiée dans Lancet Oncology en 2013 (PubMed 23540561) sur l’incidence du lymphœdème du bras après cancer du sein. L’incidence globale était de 16,6 %, de 19,9 % après curage axillaire et de 5,6 % après biopsie du ganglion sentinelle ; elle augmentait jusqu’à environ 2 ans après la chirurgie.</p>', 'i89-risque-cancer')
a('CYP2A6', [('CYP', 'CYtochrome P450'), ('2', 'famille 2'), ('A', 'sous-famille A'), ('6', 'isoenzyme 6')], 'Cytochrome P450 2A6', '<p>Enzyme hépatique qui transforme la coumarine en 7-hydroxycoumarine, métabolite non toxique. Chez un métaboliseur lent, la coumarine passe par d’autres voies qui produisent des métabolites hépatotoxiques (Farinola et Piller, Pharmacogenomics 2007).</p>', 'i89-d-benzopyrones')
a('McCormack', [('McCormack', 'nom propre : Francis X. McCormack, pneumologue américain, premier auteur de l’essai du sirolimus dans la lymphangioléiomyomatose (2011) ; ce n’est pas une abréviation')], 'Essai de McCormack et al. (2011)', '<p>Essai randomisé en double aveugle (New England Journal of Medicine 2011) chez 89 patientes atteintes de lymphangioléiomyomatose : le sirolimus pendant 12 mois a stabilisé le volume expiratoire maximal par seconde, alors qu’il déclinait sous placebo ; le déclin a repris à l’arrêt.</p>', 'i89-d-sirolimus')
a('ADAMTS3', [('A', 'A'), ('DAM', 'Disintegrin And Metalloproteinase (désintégrine et métalloprotéase)'), ('TS', 'with ThromboSpondin motifs (à motifs de thrombospondine)'), ('3', 'membre 3')], 'Protéase ADAMTS3', '<p>Protéase qui clive le précurseur peu actif du VEGF-C en forme mature ; la protéine CCBE1 favorise ce clivage (Jeltsch et al., Circulation 2014). Ses variants perte de fonction causent une forme récessive du syndrome de Hennekam.</p>', 'i89-s-vegfc')
a('N50.8', [('N50.8', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Autres affections précisées des organes génitaux de l’homme', '<p>Code CIM-10-GM 2024. Il comprend la chylocèle de la tunique vaginale (non filarienne) sans autre précision, exclue de la catégorie I89.</p>')
a('R59.1', [('R59.1', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Adénopathies généralisées', '<p>Code CIM-10-GM 2024 d’une adénopathie généralisée sans diagnostic établi : au moins deux groupes ganglionnaires non contigus sont atteints.</p>')
a('B23.8', [('B23.8', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Autres états précisés dus au virus de l’immunodéficience humaine', '<p>Code CIM-10-GM 2024 qui comprend la lymphadénopathie généralisée liée au virus de l’immunodéficience humaine ; ce tableau est exclu de la catégorie I88.</p>')
a('MIAMI', [('M', 'Malignités'), ('I', 'Infections'), ('A', 'maladies Auto-immunes'), ('M', 'Miscellaneous (causes diverses et inhabituelles)'), ('I', 'causes Iatrogènes')], 'Aide-mémoire MIAMI des causes d’adénopathie', '<p>Aide pédagogique proposée par Gaddey et Riegel (American Family Physician, 2016) pour classer les causes d’adénopathie en cinq familles. Ce n’est pas un critère officiel.</p>')
a('Kikuchi-Fujimoto', [('Kikuchi', 'Masahiro Kikuchi, pathologiste japonais'), ('Fujimoto', 'Yoshihiro Fujimoto, pathologiste japonais')], 'Maladie de Kikuchi-Fujimoto', '<p>Lymphadénite histiocytaire nécrosante bénigne de l’adulte jeune, surtout cervicale, décrite en 1972 par deux auteurs japonais. Elle peut simuler un lymphome et s’associe parfois à un lupus érythémateux systémique.</p>', 'i89-kikuchi')
a('BCL2', [('B', 'B (lymphocyte B)'), ('C', 'Cell (cellule)'), ('L', 'Lymphoma (lymphome)'), ('2', '2')], 'Protéine et gène BCL2 (B-cell lymphoma 2)', '<p>Protéine qui empêche la mort programmée des lymphocytes. Les centres germinatifs réactionnels ne l’expriment pas, alors que la plupart des lymphomes folliculaires l’expriment du fait de la translocation t(14;18) : son immunohistochimie aide à distinguer ces deux situations.</p>', 'i89-s-ganglion')
